//! Purpose: the baseline migration registry (ids, exact SQL, conditional branches) and fresh schema.
//! Scope: static data loaded once from `registry.json`, generated by scripts/extract_migrations.ts.
//! Uses:
//! rust/crates/
//! |-- storage-api/src/lib.rs
//! `-- storage-sqlite/src/transaction.rs
//! External:
//! |-- serde::Deserialize
//! `-- serde_json
//! Used by:
//! rust/crates/
//! |-- storage-sqlite/src/lib.rs
//! `-- storage-sqlite/src/migration.rs
//! Invariants: registry order equals packages/core/src/database/migration.gen.ts (38 ids). The two
//! conditional migrations port their column probes exactly:
//! 20260410174513_workspace-name copies `name` only when the old table has it, otherwise ''.
//! 20260511173437_session-metadata is a no-op when `session.metadata` already exists.
//! Contract tests: storage-sqlite/tests/migration.rs

use std::sync::LazyLock;

use opencode_storage_api::{Result, StorageError};
use rusqlite::Connection;
use serde::Deserialize;

use crate::transaction;

#[derive(Deserialize)]
struct Registry {
    schema: Vec<String>,
    migrations: Vec<Recorded>,
}

#[derive(Deserialize)]
struct Recorded {
    id: String,
    statements: Vec<String>,
}

/// One migration step.
#[derive(Debug, Clone)]
pub struct Migration {
    pub id: &'static str,
    recorded: &'static [String],
}

struct Loaded {
    schema: Vec<String>,
    migrations: Vec<Migration>,
}

static LOADED: LazyLock<Loaded> = LazyLock::new(|| {
    let registry: Registry = serde_json::from_str(include_str!("registry.json"))
        .expect("embedded migration registry is valid JSON");
    let registry: &'static Registry = Box::leak(Box::new(registry));
    Loaded {
        schema: registry.schema.clone(),
        migrations: registry
            .migrations
            .iter()
            .map(|m| Migration {
                id: m.id.as_str(),
                recorded: m.statements.as_slice(),
            })
            .collect(),
    }
});

/// Fresh schema statements (`schema.gen.ts`).
pub fn schema() -> &'static [String] {
    &LOADED.schema
}

/// Ordered registry.
pub fn all() -> &'static [Migration] {
    &LOADED.migrations
}

/// Look up one migration by id.
pub fn get(id: &str) -> Option<&'static Migration> {
    all().iter().find(|m| m.id == id)
}

/// Ordered ids.
pub fn ids() -> Vec<&'static str> {
    all().iter().map(|m| m.id).collect()
}

const WORKSPACE_NAME: &str = "20260410174513_workspace-name";
const SESSION_METADATA: &str = "20260511173437_session-metadata";

impl Migration {
    /// Statements for this database state (conditional migrations probe the schema first).
    pub fn statements(&self, conn: &Connection) -> Result<Vec<String>> {
        match self.id {
            WORKSPACE_NAME => {
                let has_name = has_column(conn, "workspace", "name")?;
                self.recorded
                    .iter()
                    .map(|sql| {
                        if !has_name || !sql.starts_with("INSERT INTO `__new_workspace`") {
                            return Ok(sql.clone());
                        }
                        let from = "`branch`, '', `directory`";
                        if !sql.contains(from) {
                            return Err(StorageError::Migration(format!(
                                "{WORKSPACE_NAME}: unexpected recorded SQL"
                            )));
                        }
                        Ok(sql.replacen(from, "`branch`, `name`, `directory`", 1))
                    })
                    .collect()
            }
            SESSION_METADATA if has_column(conn, "session", "metadata")? => Ok(Vec::new()),
            _ => Ok(self.recorded.to_vec()),
        }
    }
}

fn has_column(conn: &Connection, table: &str, column: &str) -> Result<bool> {
    let rows = transaction::query(conn, &format!("PRAGMA table_info(`{table}`)"), &[])?;
    for row in rows {
        if row.get::<String>("name")? == column {
            return Ok(true);
        }
    }
    Ok(false)
}
